(909,1667,$mw$10956D74D930630F43F389E158A0F4E8277FB754AD40CD0E04518F0564E6E54E$mw$,$mw$d6ae58e9fc93acd75052f7a8328fb42f$mw$,$mw$$mw$,$mw${"Id":1667,"StageId":3,"CategoryId":87,"Points":10,"TitleAr":"احسب الضرب القياسي للمتجهين (2,-1) و(4,3).","TitleEn":"Compute the dot product of (2,-1) and (4,3).","QuestionTextAr":"احسب الضرب القياسي للمتجهين (2,-1) و(4,3).","QuestionTextEn":"Compute the dot product of (2,-1) and (4,3).","DetailedSolutionAr":"القانون المستخدم: قانون الضرب القياسي: a·b = ax×bx + ay×by.\n\nخطوات الحل: نضرب المركبات ونجمع: ‏2×4 + (-1)×3 = 8-3 = 5.","DetailedSolutionEn":"Rule used: Dot product: a·b = ax×bx + ay×by.\n\nSolution steps: Multiply paired components and add: 2×4 + (-1)×3 = 8-3 = 5.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6657,"Order":1,"LatexCode":"5","IsCorrect":true},{"Id":6658,"Order":2,"LatexCode":"8","IsCorrect":false},{"Id":6659,"Order":3,"LatexCode":"11","IsCorrect":false},{"Id":6660,"Order":4,"LatexCode":"-5","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"اضرب المركبات المتناظرة.","En":"Multiply corresponding components."},{"Ar":"اجمع الجداءين مع مراعاة إشارة كل منهما.","En":"Add the two products, preserving their signs."}],"Title":{"Ar":"احسب الضرب القياسي للمتجهين (2,-1) و(4,3).","En":"Compute the dot product of (2,-1) and (4,3)."},"Points":10,"Options":[{"LatexCode":"5","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"8","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"8 يهمل الجداء الثاني.","En":"Eight omits the second product."}},{"LatexCode":"11","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"11 يجمع 8 و3 دون إشارة السالب.","En":"Eleven adds eight and three without the negative sign."}},{"LatexCode":"-5","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"−5 يعكس إشارة المجموع الصحيح.","En":"−5 reverses the sign of the correct sum."}}],"StageId":3,"Question":{"Ar":"احسب الضرب القياسي للمتجهين (2,-1) و(4,3).","En":"Compute the dot product of (2,-1) and (4,3)."},"Solution":{"Idea":{"Ar":"الضرب القياسي مجموع جداءات المركبات المتناظرة.","En":"The dot product is the sum of corresponding component products."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نضرب مركبتي كل محور معاً.","En":"Multiply corresponding components on each axis."},{"Ar":"$2(4)+(-1)(3)$","En":"$2(4)+(-1)(3)$"},{"Ar":"نجمع الجداءين مع مراعاة الإشارة السالبة للجداء الثاني.","En":"Add the products, retaining the negative sign of the second."}],"Result":{"Ar":"$5$","En":"$5$"},"CommonError":{"Ar":"الضرب القياسي عدد لا متجه.","En":"A dot product is a scalar, not a vector."},"FormulaLatex":"u\\cdot v=u_xv_x+u_yv_y","Substitution":{"Ar":"$8-3=5$","En":"$8-3=5$"},"Verification":{"Ar":"$4(2)+3(-1)=5$","En":"$4(2)+3(-1)=5$"}},"TrackIds":[11],"CategoryId":87,"PrimarySkillId":338,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"اضرب المركبات المتناظرة.","En":"Multiply corresponding components."},{"Ar":"اجمع الجداءين مع مراعاة إشارة كل منهما.","En":"Add the two products, preserving their signs."}],"Solution":{"Idea":{"Ar":"الضرب القياسي مجموع جداءات المركبات المتناظرة.","En":"The dot product is the sum of corresponding component products."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نضرب مركبتي كل محور معاً.","En":"Multiply corresponding components on each axis."},{"Ar":"$2(4)+(-1)(3)$","En":"$2(4)+(-1)(3)$"},{"Ar":"نجمع الجداءين مع مراعاة الإشارة السالبة للجداء الثاني.","En":"Add the products, retaining the negative sign of the second."}],"Result":{"Ar":"$5$","En":"$5$"},"CommonError":{"Ar":"الضرب القياسي عدد لا متجه.","En":"A dot product is a scalar, not a vector."},"FormulaLatex":"u\\cdot v=u_xv_x+u_yv_y","Substitution":{"Ar":"$8-3=5$","En":"$8-3=5$"},"Verification":{"Ar":"$4(2)+3(-1)=5$","En":"$4(2)+3(-1)=5$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"8 يهمل الجداء الثاني.","En":"Eight omits the second product."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"11 يجمع 8 و3 دون إشارة السالب.","En":"Eleven adds eight and three without the negative sign."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"−5 يعكس إشارة المجموع الصحيح.","En":"−5 reverses the sign of the correct sum."},"Order":4}]}$mw$,$mw$الضرب القياسي مجموع جداءات المركبات المتناظرة.

$u\cdot v=u_xv_x+u_yv_y$

1. نضرب مركبتي كل محور معاً.

2. $2(4)+(-1)(3)$

3. نجمع الجداءين مع مراعاة الإشارة السالبة للجداء الثاني.

$8-3=5$

$5$ بلا وحدة قياس

$4(2)+3(-1)=5$

الضرب القياسي عدد لا متجه.$mw$,$mw$The dot product is the sum of corresponding component products.

$u\cdot v=u_xv_x+u_yv_y$

1. Multiply corresponding components on each axis.

2. $2(4)+(-1)(3)$

3. Add the products, retaining the negative sign of the second.

$8-3=5$

$5$ Dimensionless

$4(2)+3(-1)=5$

A dot product is a scalar, not a vector.$mw$),
(911,1669,$mw$1829352FB56F57E044EE93ED3269A3B3D30ACEDF6E133201939607DEB91A95D2$mw$,$mw$5ed47325c5580221ef3962a3b6d05926$mw$,$mw$$mw$,$mw${"Id":1669,"StageId":4,"CategoryId":91,"Points":10,"TitleAr":"للدالة f(x)=(x-3)^2+2 على مجموعة الأعداد الحقيقية، ما أصغر قيمة ممكنة لـf؟","TitleEn":"For f(x)=(x-3)^2+2 over all real x, what is its minimum value?","QuestionTextAr":"للدالة f(x)=(x-3)^2+2 على مجموعة الأعداد الحقيقية، ما أصغر قيمة ممكنة لـf؟","QuestionTextEn":"For f(x)=(x-3)^2+2 over all real x, what is its minimum value?","DetailedSolutionAr":"القانون المستخدم: قاعدة المربعات: (x−a)² ≥ 0، وتتحقق القيمة الصغرى عند x=a.\n\nخطوات الحل: مربع أي عدد غير سالب، ويصير صفراً عند x=3؛ عندئذ القيمة الصغرى 2.","DetailedSolutionEn":"Rule used: Square bound: (x−a)² ≥ 0, with equality at x=a.\n\nSolution steps: A square is nonnegative and vanishes at x=3, giving the minimum value 2.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6665,"Order":1,"LatexCode":"-2","IsCorrect":false},{"Id":6666,"Order":2,"LatexCode":"0","IsCorrect":false},{"Id":6667,"Order":3,"LatexCode":"2","IsCorrect":true},{"Id":6668,"Order":4,"LatexCode":"3","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"مربع أي عدد حقيقي غير سالب.","En":"The square of a real number is nonnegative."},{"Ar":"حدّد متى يصبح الحد المربع صفراً، ثم قيّم الدالة عند تلك النقطة.","En":"Find when the squared term is zero and evaluate the function there."}],"Title":{"Ar":"للدالة f(x)=(x-3)^2+2 على مجموعة الأعداد الحقيقية، ما أصغر قيمة ممكنة لـf؟","En":"For f(x)=(x-3)^2+2 over all real x, what is its minimum value?"},"Points":10,"Options":[{"LatexCode":"-2","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"−2 أصغر من الحد الأدنى المثبت.","En":"−2 is below the proven lower bound."}},{"LatexCode":"0","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"0 لا يمكن أن يتحقق لأن الثابت موجب.","En":"Zero cannot occur because the added constant is positive."}},{"LatexCode":"2","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"3","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"3 موقع الحد الأدنى لا قيمة الدالة فيه.","En":"Three is the minimizer, not the minimum value."}}],"StageId":4,"Question":{"Ar":"للدالة f(x)=(x-3)^2+2 على مجموعة الأعداد الحقيقية، ما أصغر قيمة ممكنة لـf؟","En":"For f(x)=(x-3)^2+2 over all real x, what is its minimum value?"},"Solution":{"Idea":{"Ar":"المربع غير سالب ويبلغ الصفر عند مركزه.","En":"A square is nonnegative and vanishes at its center."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"لكل x حقيقي المربع غير سالب؛ لذلك لا تنخفض الدالة عن 2.","En":"For every real x the square is nonnegative, so the function cannot fall below two."},{"Ar":"$f(x)\\ge2$","En":"$f(x)\\ge2$"},{"Ar":"يتحقق الحد عند x=3 لأن المربع يصبح صفراً.","En":"The bound is attained at x=3 because the square vanishes."}],"Result":{"Ar":"$2$","En":"$2$"},"CommonError":{"Ar":"ميّز قيمة x عن قيمة الدالة المطلوبة.","En":"Distinguish the input x from the requested function value."},"FormulaLatex":"(x-3)^2\\ge0","Substitution":{"Ar":"$f(3)=2$","En":"$f(3)=2$"},"Verification":{"Ar":"$f(x)-f(3)=(x-3)^2\\ge0$","En":"$f(x)-f(3)=(x-3)^2\\ge0$"}},"TrackIds":[19,21],"CategoryId":91,"PrimarySkillId":343,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"مربع أي عدد حقيقي غير سالب.","En":"The square of a real number is nonnegative."},{"Ar":"حدّد متى يصبح الحد المربع صفراً، ثم قيّم الدالة عند تلك النقطة.","En":"Find when the squared term is zero and evaluate the function there."}],"Solution":{"Idea":{"Ar":"المربع غير سالب ويبلغ الصفر عند مركزه.","En":"A square is nonnegative and vanishes at its center."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"لكل x حقيقي المربع غير سالب؛ لذلك لا تنخفض الدالة عن 2.","En":"For every real x the square is nonnegative, so the function cannot fall below two."},{"Ar":"$f(x)\\ge2$","En":"$f(x)\\ge2$"},{"Ar":"يتحقق الحد عند x=3 لأن المربع يصبح صفراً.","En":"The bound is attained at x=3 because the square vanishes."}],"Result":{"Ar":"$2$","En":"$2$"},"CommonError":{"Ar":"ميّز قيمة x عن قيمة الدالة المطلوبة.","En":"Distinguish the input x from the requested function value."},"FormulaLatex":"(x-3)^2\\ge0","Substitution":{"Ar":"$f(3)=2$","En":"$f(3)=2$"},"Verification":{"Ar":"$f(x)-f(3)=(x-3)^2\\ge0$","En":"$f(x)-f(3)=(x-3)^2\\ge0$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"−2 أصغر من الحد الأدنى المثبت.","En":"−2 is below the proven lower bound."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"0 لا يمكن أن يتحقق لأن الثابت موجب.","En":"Zero cannot occur because the added constant is positive."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"3 موقع الحد الأدنى لا قيمة الدالة فيه.","En":"Three is the minimizer, not the minimum value."},"Order":4}]}$mw$,$mw$المربع غير سالب ويبلغ الصفر عند مركزه.

$(x-3)^2\ge0$

1. لكل x حقيقي المربع غير سالب؛ لذلك لا تنخفض الدالة عن 2.

2. $f(x)\ge2$

3. يتحقق الحد عند x=3 لأن المربع يصبح صفراً.

$f(3)=2$

$2$ بلا وحدة محددة

$f(x)-f(3)=(x-3)^2\ge0$

ميّز قيمة x عن قيمة الدالة المطلوبة.$mw$,$mw$A square is nonnegative and vanishes at its center.

$(x-3)^2\ge0$

1. For every real x the square is nonnegative, so the function cannot fall below two.

2. $f(x)\ge2$

3. The bound is attained at x=3 because the square vanishes.

$f(3)=2$

$2$ No specified unit

$f(x)-f(3)=(x-3)^2\ge0$

Distinguish the input x from the requested function value.$mw$),
(912,1670,$mw$DE3864064CE14B80AEA3640DD40459DFCD0A914752020C93C81422255D288B36$mw$,$mw$7d0814a5b0d80e21755c76792b2b3b57$mw$,$mw$$mw$,$mw${"Id":1670,"StageId":4,"CategoryId":91,"Points":10,"TitleAr":"أوجد قيمة x التي تحقق f'(x)=0 للدالة f(x)=x^2-6x+5.","TitleEn":"Find x where f'(x)=0 for f(x)=x^2-6x+5.","QuestionTextAr":"أوجد قيمة x التي تحقق f'(x)=0 للدالة f(x)=x^2-6x+5.","QuestionTextEn":"Find x where f'(x)=0 for f(x)=x^2-6x+5.","DetailedSolutionAr":"القانون المستخدم: شرط نقطة الثبات لدالة قابلة للاشتقاق: f'(x)=0.\n\nخطوات الحل: نشتق فنحصل على 2x-6، ومن حل المعادلة 2x-6=0 نجد x=3؛ وهي نقطة قيمة صغرى للدالة.","DetailedSolutionEn":"Rule used: Stationary-point condition for differentiable f: f'(x)=0.\n\nSolution steps: Differentiate: f'(x)=2x-6. Setting it to zero gives x=3.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6669,"Order":1,"LatexCode":"-3","IsCorrect":false},{"Id":6670,"Order":2,"LatexCode":"2","IsCorrect":false},{"Id":6671,"Order":3,"LatexCode":"3","IsCorrect":true},{"Id":6672,"Order":4,"LatexCode":"6","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"احسب المشتقة الأولى للدالة.","En":"Find the first derivative of the function."},{"Ar":"ساوِ المشتقة بالصفر وحل المعادلة في x.","En":"Set the derivative equal to zero and solve for x."}],"Title":{"Ar":"أوجد قيمة x التي تحقق f'(x)=0 للدالة f(x)=x^2-6x+5.","En":"Find x where f'(x)=0 for f(x)=x^2-6x+5."},"Points":10,"Options":[{"LatexCode":"-3","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"عند −3 تكون المشتقة −12.","En":"At −3 the derivative is −12."}},{"LatexCode":"2","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"عند 2 تكون المشتقة −2.","En":"At two the derivative is −2."}},{"LatexCode":"3","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"6","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"عند 6 تكون المشتقة 6.","En":"At six the derivative is six."}}],"StageId":4,"Question":{"Ar":"أوجد قيمة x التي تحقق f'(x)=0 للدالة f(x)=x^2-6x+5.","En":"Find x where f'(x)=0 for f(x)=x^2-6x+5."},"Solution":{"Idea":{"Ar":"النقطة الساكنة تحقق انعدام المشتقة.","En":"A stationary point satisfies a zero derivative."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"نشتق الحدود منفصلة؛ مشتقة الثابت 5 صفر.","En":"Differentiate term by term; the derivative of constant five is zero."},{"Ar":"$f'(x)=2x-6$","En":"$f'(x)=2x-6$"},{"Ar":"نساوي المشتقة بالصفر ثم نحل المعادلة الخطية.","En":"Set the derivative equal to zero and solve the linear equation."}],"Result":{"Ar":"$3$","En":"$3$"},"CommonError":{"Ar":"لا تحل f(x)=0 بدلاً من f'(x)=0.","En":"Do not solve f(x)=0 instead of f'(x)=0."},"FormulaLatex":"\\frac{d}{dx}x^n=nx^{n-1}","Substitution":{"Ar":"$2x-6=0\\Rightarrow x=3$","En":"$2x-6=0\\Rightarrow x=3$"},"Verification":{"Ar":"$f'(3)=6-6=0$","En":"$f'(3)=6-6=0$"}},"TrackIds":[19,21],"CategoryId":91,"PrimarySkillId":343,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"احسب المشتقة الأولى للدالة.","En":"Find the first derivative of the function."},{"Ar":"ساوِ المشتقة بالصفر وحل المعادلة في x.","En":"Set the derivative equal to zero and solve for x."}],"Solution":{"Idea":{"Ar":"النقطة الساكنة تحقق انعدام المشتقة.","En":"A stationary point satisfies a zero derivative."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"نشتق الحدود منفصلة؛ مشتقة الثابت 5 صفر.","En":"Differentiate term by term; the derivative of constant five is zero."},{"Ar":"$f'(x)=2x-6$","En":"$f'(x)=2x-6$"},{"Ar":"نساوي المشتقة بالصفر ثم نحل المعادلة الخطية.","En":"Set the derivative equal to zero and solve the linear equation."}],"Result":{"Ar":"$3$","En":"$3$"},"CommonError":{"Ar":"لا تحل f(x)=0 بدلاً من f'(x)=0.","En":"Do not solve f(x)=0 instead of f'(x)=0."},"FormulaLatex":"\\frac{d}{dx}x^n=nx^{n-1}","Substitution":{"Ar":"$2x-6=0\\Rightarrow x=3$","En":"$2x-6=0\\Rightarrow x=3$"},"Verification":{"Ar":"$f'(3)=6-6=0$","En":"$f'(3)=6-6=0$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"عند −3 تكون المشتقة −12.","En":"At −3 the derivative is −12."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"عند 2 تكون المشتقة −2.","En":"At two the derivative is −2."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"عند 6 تكون المشتقة 6.","En":"At six the derivative is six."},"Order":4}]}$mw$,$mw$النقطة الساكنة تحقق انعدام المشتقة.

$\frac{d}{dx}x^n=nx^{n-1}$

1. نشتق الحدود منفصلة؛ مشتقة الثابت 5 صفر.

2. $f'(x)=2x-6$

3. نساوي المشتقة بالصفر ثم نحل المعادلة الخطية.

$2x-6=0\Rightarrow x=3$

$3$ بلا وحدة محددة

$f'(3)=6-6=0$

لا تحل f(x)=0 بدلاً من f'(x)=0.$mw$,$mw$A stationary point satisfies a zero derivative.

$\frac{d}{dx}x^n=nx^{n-1}$

1. Differentiate term by term; the derivative of constant five is zero.

2. $f'(x)=2x-6$

3. Set the derivative equal to zero and solve the linear equation.

$2x-6=0\Rightarrow x=3$

$3$ No specified unit

$f'(3)=6-6=0$

Do not solve f(x)=0 instead of f'(x)=0.$mw$),
(913,1671,$mw$B71B28305467907AA9BAC7F44887A9B3EDC901AA62C5424C9047CFC0A0C498AD$mw$,$mw$7556766bb1935173a41262046e71b71a$mw$,$mw$$mw$,$mw${"Id":1671,"StageId":4,"CategoryId":91,"Points":10,"TitleAr":"نريد تصغير x^2+y^2 بشرط x+y=6 حيث x وy حقيقيان. ما الزوج الذي يحقق الأصغر؟","TitleEn":"Minimize x²+y² subject to x+y=6 for real x and y. Which pair gives the minimum?","QuestionTextAr":"نريد تصغير x^2+y^2 بشرط x+y=6 حيث x وy حقيقيان. ما الزوج الذي يحقق الأصغر؟","QuestionTextEn":"Minimize x²+y² subject to x+y=6 for real x and y. Which pair gives the minimum?","DetailedSolutionAr":"القانون المستخدم: بالإحلال من القيد x+y=c نكتب y=c−x ونصغّر دالة متغير واحد.\n\nخطوات الحل: من تماثل الدالة أو بإكمال المربع، تتحقق القيمة الأصغر عند x=y=3.","DetailedSolutionEn":"Rule used: Use the linear constraint x+y=c to substitute y=c−x and minimize a one-variable function.\n\nSolution steps: Substitute y=6-x and complete the square; the minimum occurs at x=y=3.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6673,"Order":1,"LatexCode":"(0,6)","IsCorrect":false},{"Id":6674,"Order":2,"LatexCode":"(2,4)","IsCorrect":false},{"Id":6675,"Order":3,"LatexCode":"(3,3)","IsCorrect":true},{"Id":6676,"Order":4,"LatexCode":"(6,0)","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"استخدم القيد للتعبير عن y بدلالة x.","En":"Use the constraint to express y in terms of x."},{"Ar":"عوّض في x²+y² ثم أكمل المربع أو اشتق الدالة ذات المتغير الواحد.","En":"Substitute into x²+y², then complete the square or differentiate the one-variable function."}],"Title":{"Ar":"نريد تصغير x^2+y^2 بشرط x+y=6 حيث x وy حقيقيان. ما الزوج الذي يحقق الأصغر؟","En":"Minimize x²+y² subject to x+y=6 for real x and y. Which pair gives the minimum?"},"Points":10,"Options":[{"LatexCode":"(0,6)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"(0,6) يعطي 36 لا 18.","En":"(0,6) gives 36, not eighteen."}},{"LatexCode":"(2,4)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"(2,4) يعطي 20، أكبر من 18.","En":"(2,4) gives twenty, above eighteen."}},{"LatexCode":"(3,3)","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"(6,0)","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"(6,0) يعطي 36.","En":"(6,0) gives 36."}}],"StageId":4,"Question":{"Ar":"نريد تصغير x^2+y^2 بشرط x+y=6 حيث x وy حقيقيان. ما الزوج الذي يحقق الأصغر؟","En":"Minimize x²+y² subject to x+y=6 for real x and y. Which pair gives the minimum?"},"Solution":{"Idea":{"Ar":"نعوض القيد الخطي ثم نكمل المربع.","En":"Substitute the linear constraint, then complete the square."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"نعوض القيد في دالة الهدف فنحصل على كثيرة حدود في x وحده.","En":"Substitute the constraint into the objective to get a polynomial in x alone."},{"Ar":"$x^2+(6-x)^2=2(x-3)^2+18$","En":"$x^2+(6-x)^2=2(x-3)^2+18$"},{"Ar":"بإكمال المربع يتضح أن 18 حد أدنى شامل يتحقق فقط عند x=3.","En":"Completing the square gives a global lower bound of eighteen attained only at x=3."}],"Result":{"Ar":"$(3,3)$","En":"$(3,3)$"},"CommonError":{"Ar":"تحقق من القيد ومن الحد الأدنى الشامل لا مجرد نقطة ممكنة.","En":"Verify both feasibility and the global minimum, not merely a feasible point."},"FormulaLatex":"y=6-x","Substitution":{"Ar":"$x=3,\\quad y=3$","En":"$x=3,\\quad y=3$"},"Verification":{"Ar":"$3+3=6,\\quad3^2+3^2=18$","En":"$3+3=6,\\quad3^2+3^2=18$"}},"TrackIds":[19,21],"CategoryId":91,"PrimarySkillId":341,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"استخدم القيد للتعبير عن y بدلالة x.","En":"Use the constraint to express y in terms of x."},{"Ar":"عوّض في x²+y² ثم أكمل المربع أو اشتق الدالة ذات المتغير الواحد.","En":"Substitute into x²+y², then complete the square or differentiate the one-variable function."}],"Solution":{"Idea":{"Ar":"نعوض القيد الخطي ثم نكمل المربع.","En":"Substitute the linear constraint, then complete the square."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"نعوض القيد في دالة الهدف فنحصل على كثيرة حدود في x وحده.","En":"Substitute the constraint into the objective to get a polynomial in x alone."},{"Ar":"$x^2+(6-x)^2=2(x-3)^2+18$","En":"$x^2+(6-x)^2=2(x-3)^2+18$"},{"Ar":"بإكمال المربع يتضح أن 18 حد أدنى شامل يتحقق فقط عند x=3.","En":"Completing the square gives a global lower bound of eighteen attained only at x=3."}],"Result":{"Ar":"$(3,3)$","En":"$(3,3)$"},"CommonError":{"Ar":"تحقق من القيد ومن الحد الأدنى الشامل لا مجرد نقطة ممكنة.","En":"Verify both feasibility and the global minimum, not merely a feasible point."},"FormulaLatex":"y=6-x","Substitution":{"Ar":"$x=3,\\quad y=3$","En":"$x=3,\\quad y=3$"},"Verification":{"Ar":"$3+3=6,\\quad3^2+3^2=18$","En":"$3+3=6,\\quad3^2+3^2=18$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"(0,6) يعطي 36 لا 18.","En":"(0,6) gives 36, not eighteen."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"(2,4) يعطي 20، أكبر من 18.","En":"(2,4) gives twenty, above eighteen."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"(6,0) يعطي 36.","En":"(6,0) gives 36."},"Order":4}]}$mw$,$mw$نعوض القيد الخطي ثم نكمل المربع.

$y=6-x$

1. نعوض القيد في دالة الهدف فنحصل على كثيرة حدود في x وحده.

2. $x^2+(6-x)^2=2(x-3)^2+18$

3. بإكمال المربع يتضح أن 18 حد أدنى شامل يتحقق فقط عند x=3.

$x=3,\quad y=3$

$(3,3)$ بلا وحدة محددة

$3+3=6,\quad3^2+3^2=18$

تحقق من القيد ومن الحد الأدنى الشامل لا مجرد نقطة ممكنة.$mw$,$mw$Substitute the linear constraint, then complete the square.

$y=6-x$

1. Substitute the constraint into the objective to get a polynomial in x alone.

2. $x^2+(6-x)^2=2(x-3)^2+18$

3. Completing the square gives a global lower bound of eighteen attained only at x=3.

$x=3,\quad y=3$

$(3,3)$ No specified unit

$3+3=6,\quad3^2+3^2=18$

Verify both feasibility and the global minimum, not merely a feasible point.$mw$),
(914,1672,$mw$C3C1ECA6CC4FC60337682E4C1904BD755368DAC2538FD9B5B1AA86CB6B149BD7$mw$,$mw$427fe83e80ee4032dfde06c349d1ca80$mw$,$mw$$mw$,$mw${"Id":1672,"StageId":4,"CategoryId":91,"Points":10,"TitleAr":"إذا كان x وy غير سالبين ومجموعهما 10، فما أكبر قيمة للجداء xy؟","TitleEn":"For nonnegative x and y with x+y=10, what is the greatest possible value of xy?","QuestionTextAr":"إذا كان x وy غير سالبين ومجموعهما 10، فما أكبر قيمة للجداء xy؟","QuestionTextEn":"For nonnegative x and y with x+y=10, what is the greatest possible value of xy?","DetailedSolutionAr":"القانون المستخدم: عند x+y=c مع x,y≥0: ‏xy ≤ (c/2)²، والمساواة عندما x=y.\n\nخطوات الحل: يبلغ الجداء قيمته الكبرى عند تساوي العددين x=y=5، وبالتالي xy=25.","DetailedSolutionEn":"Rule used: For x+y=c and x,y≥0: xy ≤ (c/2)², with equality at x=y.\n\nSolution steps: The product is maximized when x=y=5, so the maximum is 25.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":6677,"Order":1,"LatexCode":"20","IsCorrect":false},{"Id":6678,"Order":2,"LatexCode":"24","IsCorrect":false},{"Id":6679,"Order":3,"LatexCode":"25","IsCorrect":true},{"Id":6680,"Order":4,"LatexCode":"50","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"عندما يكون مجموع عددين غير سالبين ثابتاً يمكن مقارنة الوسط الحسابي والهندسي.","En":"For nonnegative numbers of fixed sum, compare arithmetic and geometric means."},{"Ar":"تتحقق المساواة عندما يتساوى العددان؛ أو عوّض y=10−x وابحث عن رأس القطع المكافئ.","En":"Equality occurs when the numbers match; alternatively substitute y=10−x and find the quadratic vertex."}],"Title":{"Ar":"إذا كان x وy غير سالبين ومجموعهما 10، فما أكبر قيمة للجداء xy؟","En":"For nonnegative x and y with x+y=10, what is the greatest possible value of xy?"},"Points":10,"Options":[{"LatexCode":"20","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"20 قيمة ممكنة لكنها دون 25.","En":"Twenty is feasible but below 25."}},{"LatexCode":"24","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"24 يتحقق عند 4 و6 لكنه ليس الأكبر.","En":"Twenty-four occurs at four and six but is not maximal."}},{"LatexCode":"25","IsCorrect":true,"ErrorType":"","Reason":null},{"LatexCode":"50","IsCorrect":false,"ErrorType":"incorrect-option","Reason":{"Ar":"50 يتجاوز الحد الأعلى المثبت.","En":"Fifty exceeds the proven upper bound."}}],"StageId":4,"Question":{"Ar":"إذا كان x وy غير سالبين ومجموعهما 10، فما أكبر قيمة للجداء xy؟","En":"For nonnegative x and y with x+y=10, what is the greatest possible value of xy?"},"Solution":{"Idea":{"Ar":"عند ثبات مجموع عددين غير سالبين يكون حاصل ضربهما أعظم ما يمكن عند تساويهما.","En":"For a fixed nonnegative sum, the product is maximal when the terms are equal."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"نعوض y=10−x ونكمل المربع في الجداء.","En":"Substitute y=10−x and complete the square in the product."},{"Ar":"$0\\le x\\le10$","En":"$0\\le x\\le10$"},{"Ar":"المربع غير سالب؛ لذا 25 حد أعلى يتحقق عند x=5، وهي قيمة مسموحة.","En":"The square is nonnegative, so 25 is an upper bound attained at feasible x=5."}],"Result":{"Ar":"$25$","En":"$25$"},"CommonError":{"Ar":"لا تكتف باختيار زوج يحقق القيد؛ افحص قيمة الهدف.","En":"Do not stop at a feasible pair; check the objective value."},"FormulaLatex":"xy=x(10-x)=25-(x-5)^2","Substitution":{"Ar":"$xy\\le25,\\quad x=y=5$","En":"$xy\\le25,\\quad x=y=5$"},"Verification":{"Ar":"$5+5=10,\\quad5\\cdot5=25$","En":"$5+5=10,\\quad5\\cdot5=25$"}},"TrackIds":[19,21],"CategoryId":91,"PrimarySkillId":341,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"عندما يكون مجموع عددين غير سالبين ثابتاً يمكن مقارنة الوسط الحسابي والهندسي.","En":"For nonnegative numbers of fixed sum, compare arithmetic and geometric means."},{"Ar":"تتحقق المساواة عندما يتساوى العددان؛ أو عوّض y=10−x وابحث عن رأس القطع المكافئ.","En":"Equality occurs when the numbers match; alternatively substitute y=10−x and find the quadratic vertex."}],"Solution":{"Idea":{"Ar":"عند ثبات مجموع عددين غير سالبين يكون حاصل ضربهما أعظم ما يمكن عند تساويهما.","En":"For a fixed nonnegative sum, the product is maximal when the terms are equal."},"Unit":{"Ar":"بلا وحدة محددة","En":"No specified unit"},"Steps":[{"Ar":"نعوض y=10−x ونكمل المربع في الجداء.","En":"Substitute y=10−x and complete the square in the product."},{"Ar":"$0\\le x\\le10$","En":"$0\\le x\\le10$"},{"Ar":"المربع غير سالب؛ لذا 25 حد أعلى يتحقق عند x=5، وهي قيمة مسموحة.","En":"The square is nonnegative, so 25 is an upper bound attained at feasible x=5."}],"Result":{"Ar":"$25$","En":"$25$"},"CommonError":{"Ar":"لا تكتف باختيار زوج يحقق القيد؛ افحص قيمة الهدف.","En":"Do not stop at a feasible pair; check the objective value."},"FormulaLatex":"xy=x(10-x)=25-(x-5)^2","Substitution":{"Ar":"$xy\\le25,\\quad x=y=5$","En":"$xy\\le25,\\quad x=y=5$"},"Verification":{"Ar":"$5+5=10,\\quad5\\cdot5=25$","En":"$5+5=10,\\quad5\\cdot5=25$"}},"Distractors":[{"ErrorType":"incorrect-option","Reason":{"Ar":"20 قيمة ممكنة لكنها دون 25.","En":"Twenty is feasible but below 25."},"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"24 يتحقق عند 4 و6 لكنه ليس الأكبر.","En":"Twenty-four occurs at four and six but is not maximal."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"50 يتجاوز الحد الأعلى المثبت.","En":"Fifty exceeds the proven upper bound."},"Order":4}]}$mw$,$mw$عند ثبات مجموع عددين غير سالبين يكون حاصل ضربهما أعظم ما يمكن عند تساويهما.

$xy=x(10-x)=25-(x-5)^2$

1. نعوض y=10−x ونكمل المربع في الجداء.

2. $0\le x\le10$

3. المربع غير سالب؛ لذا 25 حد أعلى يتحقق عند x=5، وهي قيمة مسموحة.

$xy\le25,\quad x=y=5$

$25$ بلا وحدة محددة

$5+5=10,\quad5\cdot5=25$

لا تكتف باختيار زوج يحقق القيد؛ افحص قيمة الهدف.$mw$,$mw$For a fixed nonnegative sum, the product is maximal when the terms are equal.

$xy=x(10-x)=25-(x-5)^2$

1. Substitute y=10−x and complete the square in the product.

2. $0\le x\le10$

3. The square is nonnegative, so 25 is an upper bound attained at feasible x=5.

$xy\le25,\quad x=y=5$

$25$ No specified unit

$5+5=10,\quad5\cdot5=25$

Do not stop at a feasible pair; check the objective value.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
